fn receive_handles(h: &mut Harness, queue: &str, n: u64) -> Vec<String> {
    let r = h.ok(json!({"Command": "ReceiveMessage", "QueueName": queue, "MaxMessages": n}));
    r["Messages"]
        .as_array()
        .unwrap()
        .iter()
